        score += new_penalty;
    }

    // Encourage bins whose residual is near the mean
    score += diff_from_mean.powi(2) * 4.0;

    // Small constant for new‑bin recognition
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic progress factor (0..1)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Base score: penalise large residuals more sharply
    let mut score = (post_residual as f64).powf(1.1);

    // Reward packing that moves residual below the current mean
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    } else {
        // Slight penalty if residual stays above the mean
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // If this is the only bin that can take the item, strongly favour it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Look‑ahead: avoid leaving space that the next item cannot fit
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Penalise the use of an existing bin when many bins are open
    score += (open_bins_count as f64) * 0.2;

    // Near the end of the stream: prefer to open a new bin if the residual
    // will leave a hole that is hard to fill
    if progress > 0.8 {
        let residual_ratio = post_residual as f64 / bin_capacity as f64;
        score += (1.0 - residual_ratio) * 10.0;
    }

    // Size‑fit bonus: pack the item tightly into the bin
    if bin_residual >= item_size {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.85 {
            score -= 12.0;
        }
    }

    // New‑bin candidate: penalise opening a new bin unless it is clearly better
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ---------- Progress ----------
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // ---------- Residual ratios ----------
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let fit_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    let diff_from_mean = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    // ---------- Base score ----------
    let mut score = residual_ratio * 12.0;

    // ---------- Fine‑grained fit bonus ----------
    if bin_residual >= item_size {
        if fit_ratio > 0.995 {
            score -= 30.0;
        } else if fit_ratio > 0.98 {
            score -= 20.0;
        } else if fit_ratio > 0.96 {
            score -= 10.0;
        } else {
            score -= 5.0;
        }
    }

    // ---------- Competition penalty ----------
    if fitting_bins_count > 0 {
        score += ((fitting_bins_count as f64 - 1.0).powi(2)) * 0.4;
    }

    // ---------- Look‑ahead ----------
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next > post {
            score += 8.0;
        } else if next * 1.05 > post {
            score += 3.0;
        }
        if (next - post).abs() < 3.0 {
            score -= 4.0;
        }
    }

    // ---------- Open bin count penalty ----------
    if open_bins_count > 0 {
        let penalty = ((open_bins_count as f64).ln() * 0.25).powi(2);
        score += penalty;
    }

    // ---------- Progress boost ----------
    if progress > 0.85 {
        score += (1.0 - residual_ratio) * 25.0;
    }

    // ---------- New‑bin candidate handling ----------
    if bin_residual == bin_capacity {
        let mut new_penalty = 2.5;
        if open_bins_count > 8 {
            new_penalty -= 0.2 * ((open_bins_count as f64) - 8.0);
        }
        if mean_residual > bin_capacity as f64 * 0.55 {
            new_penalty += 1.5;
        }
        if next_item_size > 0
            && next_item_size as f64 > post_residual as f64 * 1.15
        {
            new_penalty += 2.0;
        }
        if progress < 0.1 && open_bins_count > 4 {
            new_penalty -= 0.5;
        }
        if progress > 0.9 {
            new_penalty += 0.5;
        }
        score += new_penalty;
    }

    // ---------- Near‑mean residual bonus ----------
    score += diff_from_mean.powi(2) * 4.0;

    // ---------- Small constant for new‑bin recognition ----------
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}
